package e.e.a;
import android.view.*;
import android.widget.*;
import java.util.*;
public final class PortraitTimeline213 {
 private static final Map<View,State> STATES=new WeakHashMap<View,State>();
 static View find(View v,String n){return v.findViewById(v.getResources().getIdentifier(n,"id",v.getContext().getPackageName()));}
 static ViewGroup.LayoutParams copy(ViewGroup.LayoutParams p){if(p instanceof RelativeLayout.LayoutParams)return new RelativeLayout.LayoutParams((RelativeLayout.LayoutParams)p);if(p instanceof LinearLayout.LayoutParams)return new LinearLayout.LayoutParams((LinearLayout.LayoutParams)p);if(p instanceof ViewGroup.MarginLayoutParams)return new ViewGroup.MarginLayoutParams((ViewGroup.MarginLayoutParams)p);return new ViewGroup.LayoutParams(p);}
 public static void update(View root){if(root==null||root.getResources().getConfiguration().orientation!=1){restore(root);return;}View frame=find(root,"videoLayout"),controller=find(root,"controller");if(!(frame instanceof RelativeLayout)||controller==null||!(controller.getParent() instanceof ViewGroup))return;State s=STATES.get(root);if(s==null){s=new State(root,(RelativeLayout)frame,controller);STATES.put(root,s);}s.apply();}
 public static void restore(View root){State s=STATES.remove(root);if(s!=null)s.restore();}
 static final class State implements View.OnAttachStateChangeListener,View.OnLayoutChangeListener {final View root,controller;final RelativeLayout frame;final ViewGroup parent;final ViewGroup autoHost;final int index;final ViewGroup.LayoutParams original;final android.graphics.drawable.Drawable bg;final View bottom;final ViewGroup.LayoutParams bottomParams;
 State(View r,RelativeLayout f,View c){root=r;frame=f;controller=c;parent=(ViewGroup)c.getParent();View status=find(r,"statuslay");autoHost=status instanceof RelativeLayout&&inside(status,f)?(ViewGroup)status:f;index=parent.indexOfChild(c);original=copy(c.getLayoutParams());bg=c.getBackground();bottom=find(r,"bottommenulay");bottomParams=bottom==null?null:copy(bottom.getLayoutParams());root.addOnAttachStateChangeListener(this);c.addOnLayoutChangeListener(this);place();}
 static boolean inside(View view,View ancestor){for(View current=view;current!=null;){if(current==ancestor)return true;ViewParent p=current.getParent();current=p instanceof View?(View)p:null;}return false;}
 void place(){ViewGroup target=PlayerControlsDock.enabled(root.getContext())?frame:autoHost;if(controller.getParent()==target){RelativeLayout.LayoutParams current=controller.getLayoutParams() instanceof RelativeLayout.LayoutParams?(RelativeLayout.LayoutParams)controller.getLayoutParams():null;if(current==null||current.getRule(RelativeLayout.ALIGN_PARENT_BOTTOM)==0){RelativeLayout.LayoutParams p=new RelativeLayout.LayoutParams(-1,-2);p.addRule(RelativeLayout.ALIGN_PARENT_BOTTOM);controller.setLayoutParams(p);}return;}ViewParent current=controller.getParent();if(current instanceof ViewGroup)((ViewGroup)current).removeView(controller);RelativeLayout.LayoutParams p=new RelativeLayout.LayoutParams(-1,-2);p.addRule(RelativeLayout.ALIGN_PARENT_BOTTOM);target.addView(controller,p);}
 void apply(){place();controller.setTranslationY(0);controller.setTranslationX(0);controller.setBackgroundColor(0x99000000);controller.bringToFront();if(bottom!=null&&bottom.getLayoutParams() instanceof RelativeLayout.LayoutParams){RelativeLayout.LayoutParams p=(RelativeLayout.LayoutParams)bottom.getLayoutParams();int margin=Math.max(controller.getHeight(),controller.getMeasuredHeight());if(p.getRule(RelativeLayout.ABOVE)!=0||p.getRule(RelativeLayout.ALIGN_PARENT_BOTTOM)==0||p.bottomMargin!=margin){p.removeRule(RelativeLayout.ABOVE);p.addRule(RelativeLayout.ALIGN_PARENT_BOTTOM);p.bottomMargin=margin;bottom.setLayoutParams(p);}}}
 void restore(){root.removeOnAttachStateChangeListener(this);controller.removeOnLayoutChangeListener(this);if(bottom!=null&&bottomParams!=null)bottom.setLayoutParams(bottomParams);if(controller.getParent()==frame||controller.getParent()==autoHost){((ViewGroup)controller.getParent()).removeView(controller);parent.addView(controller,Math.min(index,parent.getChildCount()),original);}controller.setBackground(bg);}
 public void onLayoutChange(View v,int l,int t,int r,int b,int ol,int ot,int or,int ob){apply();}
 public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){PortraitTimeline213.restore(root);}}
}
